import{_ as o,C as a,o as n,c as r,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const m=JSON.parse('{"title":"Run control for agents","description":"Give a coding agent on your machine the test runs your editor or the desktop app starts, as MCP tools: it follows a run, stops it, reads the stopped page as its ARIA snapshot, acts on it by ref and has Piwi write the code there, which you see and can undo.","frontmatter":{"title":"Run control for agents","description":"Give a coding agent on your machine the test runs your editor or the desktop app starts, as MCP tools: it follows a run, stops it, reads the stopped page as its ARIA snapshot, acts on it by ref and has Piwi write the code there, which you see and can undo.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/agent-run-control.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/agent-run-control.html"}],["meta",{"property":"og:title","content":"Run control for agents | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Give a coding agent on your machine the test runs your editor or the desktop app starts, as MCP tools: it follows a run, stops it, reads the stopped page as its ARIA snapshot, acts on it by ref and has Piwi write the code there, which you see and can undo."}]]},"headers":[],"relativePath":"features/agent-run-control.md","filePath":"features/agent-run-control.md","lastUpdated":1793426140000}'),l={name:"features/agent-run-control.md"};function c(p,e,u,g,w,k){const s=a("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"run-control-for-agents",tabindex:"-1"},[i("Run control for agents "),t("a",{class:"header-anchor",href:"#run-control-for-agents","aria-label":'Permalink to "Run control for agents"'},"​")],-1)),h(s,{reporter:"",fixtures:""}),e[1]||(e[1]=d(`<p>A coding agent on your machine (Claude Code, Copilot, Cursor, the JetBrains AI Assistant) can work with a test run the way you do with <a href="./editor-run-control.html">Pause and step from the editor</a> and the <a href="./runs-window.html">Runs window</a>: follow the run, stop it, look at the stopped page, act on it, and have the code written at the stopped line. The editor service serves the runs of its window (in a JetBrains IDE, its project) as an MCP server of its own, apart from Piwi&#39;s <a href="./mcp.html">MCP server</a>, which reads your suite&#39;s history on an instance; the <a href="#in-the-desktop-app">desktop app</a> serves its own.</p><h2 id="connect-your-agent" tabindex="-1">Connect your agent <a class="header-anchor" href="#connect-your-agent" aria-label="Permalink to &quot;Connect your agent&quot;">​</a></h2><p>The server listens on <code>127.0.0.1</code> once the editor extension starts, at a port and behind a token the extension keeps for this workspace (in a JetBrains IDE, this project): a configuration you copy once keeps working after a restart. If another program holds that port, the server moves, with a new token, and says so.</p><table tabindex="0"><thead><tr><th>Agent</th><th>What it takes</th></tr></thead><tbody><tr><td>VS Code&#39;s own agent (1.101 and later)</td><td>Nothing to set: the extension lists the server as <strong>Piwi runs</strong>, beside <strong>Piwi</strong></td></tr><tr><td>Claude Code, Cursor and other agents that connect over HTTP</td><td>The <code>mcpServers</code> entry of type <code>http</code> below, with the token as a bearer header</td></tr><tr><td>The JetBrains AI Assistant, Claude Desktop and agents that only start commands</td><td>An <code>mcpServers</code> entry that runs <code>mcp-remote</code>, a small Node bridge, at one exact release</td></tr></tbody></table><ul><li><p><strong>From VS Code</strong>: <strong>Piwi: Copy the runs&#39; MCP server configuration for agents</strong> asks which, then copies the entry:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;piwi-runs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:41234/mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer …&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Claude Code reads it in your user settings (<code>claude mcp add-json</code> with <code>--scope user</code>), Cursor in <code>~/.cursor/mcp.json</code>; the other choice is VS Code&#39;s own <code>mcp.json</code>.</p></li><li><p><strong>From a JetBrains IDE</strong>: <strong>Tools → Piwi → Copy the Runs&#39; MCP Server Configuration for Claude Code or Cursor</strong> copies the same entry; <strong>…for Agents</strong> copies one that runs <code>npx -y mcp-remote@0.14.3 &lt;url&gt; --transport http-only</code>, the token in <code>env</code>, for the AI Assistant (<strong>Settings → Tools → AI Assistant → Model Context Protocol</strong>), which has no public way for a plugin to add a server.</p></li></ul><p><strong>The configuration holds the token.</strong> Keep it in your user settings, never in a file of the repository such as a project&#39;s <code>.mcp.json</code>: whoever reads it can drive your runs while the editor is open. <strong>Reset the token</strong> (<strong>Piwi: Reset the runs&#39; MCP server token</strong>; <strong>Tools → Piwi → Reset the Runs&#39; MCP Server Token</strong>) gives the server a new one: an agent with the old one is refused until you copy the configuration again. <code>piwi.serveRunsToAgents</code> in VS Code, and <strong>Settings → Tools → Piwi</strong> in a JetBrains IDE, turn the server off.</p><h2 id="the-tools" tabindex="-1">The tools <a class="header-anchor" href="#the-tools" aria-label="Permalink to &quot;The tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>run_list</code></td><td>The runs of the window, their workers, the test each one runs and where it stands stopped</td></tr><tr><td><code>run_follow</code></td><td>The run&#39;s events since a cursor: each test&#39;s start and end, each call with its place in your code and its result, the stops, and the page&#39;s navigations, console errors, uncaught errors and failed requests. It waits up to 25 seconds, and answers at once while the run is stopped or ended</td></tr><tr><td><code>run_control</code></td><td>Pause, Step, Run to a line, Resume, Finish or <a href="./end-the-test.html">End the test</a>, answered when the run stops again, with the page&#39;s snapshot, when the test it ended ends, or when the run ends</td></tr><tr><td><code>page_snapshot</code></td><td>The stopped page&#39;s ARIA snapshot in AI mode, a ref per element (<code>[ref=e5]</code>), to a depth you choose, with an image of the page when asked</td></tr><tr><td><code>page_act</code></td><td>Click, fill, press a key, check, uncheck or select an option on an element by its ref, answered with the page&#39;s change</td></tr><tr><td><code>page_locator</code></td><td>Piwi&#39;s locators for an element by its ref, ranked as <a href="./pick-an-element.html">Pick a locator</a> ranks them, each checked to find it alone</td></tr><tr><td><code>code_write</code></td><td>The steps <code>page_act</code> took, the element&#39;s locator in place of the stopped line&#39;s, or an assertion on it, written by the editor</td></tr></tbody></table><p>An agent reads the page as text: the first snapshot whole (or to a depth), then what each stop and action changed. An image costs more, and comes only when asked.</p><p><strong>The steps the agent takes</strong> are kept as yours are when you record: each with the element&#39;s best locator, the project&#39;s test id attribute first and the suite&#39;s own locators preferred. <code>code_write</code> renders them with Piwi&#39;s generator, as <a href="./editor-stop-code.html">Code from a pause</a> does, and the editor writes them above the stopped line as one edit: one undo removes it. The test goes on with the code it started with: the new lines run next time.</p><p>A run&#39;s calls and page events are told until two minutes after the agent&#39;s last call on it; an action the page answers late may still take effect, kept as a step, and <code>run_follow</code> says so.</p><p><strong>An assertion on an element&#39;s text</strong> checks the whole text, as the page shows it now (<code>toHaveText</code>); for a text longer than 1,000 characters, it checks that the element contains its first words (<code>toContainText</code>, up to 200 characters). Piwi refuses to write a secret field&#39;s value, and a text or a value that holds a credential.</p><h2 id="what-keeps-it-safe" tabindex="-1">What keeps it safe <a class="header-anchor" href="#what-keeps-it-safe" aria-label="Permalink to &quot;What keeps it safe&quot;">​</a></h2><ul><li><strong>Only this machine, only this window.</strong> The server answers a request to its own address on <code>127.0.0.1</code> with the token, and refuses any other name for the machine and any request a browser sends (it carries an <code>Origin</code>). It serves the runs this window started, and those <a href="./terminal-runs.html">started outside Piwi</a> that follow it, and nothing of an instance.</li><li><strong>Only a stopped page, only the actions named.</strong> An action needs the stop it answers, and goes nowhere once the test went on. The tools take a closed set of arguments; none evaluates code, reads a file or runs a command. Code reaches your files only through the editor, as an edit you see.</li><li><strong>The page is untrusted.</strong> A page can hold text written to steer a model. Everything that comes from it (its snapshot, its address and title, an element&#39;s name, text and value, the locators built from them, its console, its errors, its requests, and what the test says when a read of it fails) comes back apart from Piwi&#39;s own answer, between two markers that share a random value the page cannot know, and every tool&#39;s description tells the agent to read it as data, never as instructions. An image comes after a line that says it is the page&#39;s too.</li><li><strong>Secrets stay hidden.</strong> The value of a password field, a one-time code and a card&#39;s number or security code is never sent: its line in the snapshot reads <code>&lt;hidden&gt;</code>, in every frame, the image masks the field, and no assertion writes it. Tokens and credentials in the page&#39;s text, its addresses and the locators <code>page_locator</code> shows are hidden, as on Piwi&#39;s other surfaces.</li><li><strong>You watch it happen.</strong> The agent&#39;s stops show in the editor and the Runs window as yours do, the editor&#39;s as <code>Paused by the agent · …</code>; its first action at a stop says so in a notification; the code it has written names it (<code>Piwi wrote the steps the agent took above checkout.spec.ts:30.</code>). You can take over at any stop.</li></ul><h2 id="in-the-desktop-app" tabindex="-1">In the desktop app <a class="header-anchor" href="#in-the-desktop-app" aria-label="Permalink to &quot;In the desktop app&quot;">​</a></h2><p>The <a href="./desktop-runs.html#for-agents">desktop app</a> serves the same tools for the runs it starts, from its own MCP server. There, <code>code_write</code> writes no file: the code waits in the <strong>Local runs</strong> tray to copy, and comes back to the agent. A run nobody attends, such as a Flake Lab run or a bisect, is not served.</p><h2 id="share-with-playwright-tools" tabindex="-1">Share with Playwright tools <a class="header-anchor" href="#share-with-playwright-tools" aria-label="Permalink to &quot;Share with Playwright tools&quot;">​</a></h2><p>At a stop, <strong>Share with Playwright tools</strong> (the stop&#39;s hover and <strong>Piwi: Share the stopped test&#39;s browser with Playwright tools</strong> in VS Code; the stop&#39;s menu and <strong>Tools → Piwi</strong> in a JetBrains IDE) binds the test&#39;s browser for Playwright&#39;s own tools, so <code>npx playwright cli attach piwi-&lt;run&gt;-w&lt;worker&gt;</code> and Playwright&#39;s dashboard can join it. It is off until you ask, every time, and asks first: a shared browser is open to any process of yours, which can read its pages and run code in them. It is shared until the test ends, and no agent can share it.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>A remote window</strong> (SSH, a dev container, Gateway) runs the server on the remote machine: an agent there reaches it.</li><li>An action needs Playwright 1.64 or later and a <code>@piwitests/reporter</code> at least as recent as the editor extension; at an older one&#39;s stops, the tools say what it cannot do.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-run-control.html">Pause and step from the editor</a></li><li><a href="./editor-stop-code.html">Code from a pause</a></li><li><a href="./mcp.html">MCP server</a></li><li><a href="./runs-window.html">Runs window</a></li></ul>`,22))])}const y=o(l,[["render",c]]);export{m as __pageData,y as default};
